int rfcomm_get_dev_list(void __user *arg)
{
    struct rfcomm_dev *dev;
    struct rfcomm_dev_list __user *ulist;
    struct rfcomm_dev_list list;
    int i = 0, rc = -EFAULT;
    size_t size;

    if (copy_from_user(&list, arg, sizeof(list)))
        return -EFAULT;

    size = list.count * sizeof(struct rfcomm_dev_info);
    if (size == 0)
        return 0;

    list.data = kmalloc(size, GFP_KERNEL);
    if (!list.data)
        return -ENOMEM;

    rc = -EFAULT;

    rcu_read_lock();
    list_for_each_rcu(dev, &rfcomm_dev_list) {
        if (!dev->owner) {
            continue;
        }

        if (i >= list.count)
            break;

        list.data[i].id = dev->id;
        list.data[i].state = dev->state;
        list.data[i].mtu = dev->mtu;
        list.data[i].flags = dev->flags;
        i++;
    }
    rcu_read_unlock();

    if (copy_to_user(arg, &list, sizeof(list))) {
        kfree(list.data);
        return -EFAULT;
    }

    kfree(list.data);
    return 0;
}

int get_rfcomm_devices(void __user *arg) {
    int num_devs;
    struct rfcomm_dev *dev;
    struct rfcomm_dev_list *list;
    int i = 0;

    if (get_user(num_devs, (int __user *)arg))
        return -EFAULT;

    if (num_devs <= 0)
        return -EINVAL;

    list = kmalloc(num_devs * sizeof(*list), GFP_KERNEL);
    if (!list)
        return -ENOMEM;

    lock_device_list();

    list_for_each_entry(dev, &rfcomm_dev_list, list) {
        if (dev->state == RFCOMM_DEV_RELEASING)
            continue;

        if (i >= num_devs)
            break;

        list[i].id = dev->id;
        list[i].state = dev->state;
        strlcpy(list[i].name, dev->name, RFCOMM_NAME_SIZE);
        i++;
    }

    unlock_device_list();

    if (copy_to_user(arg, list, i * sizeof(*list))) {
        kfree(list);
        return -EFAULT;
    }

    kfree(list);
    return 0;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>
#include <linux/mutex.h>

int get_rfcomm_devices(void __user *arg) {
    int num_devs;
    int rc;
    struct rfcomm_dev **d;
    int i = 0;

    if (get_user(num_devs, (int __user *)arg))
        return -EFAULT;

    if (num_devs < 0)
        return -EINVAL;

    d = kmalloc_array(num_devs, sizeof(struct rfcomm_dev *), GFP_KERNEL);
    if (!d)
        return -ENOMEM;

    mutex_lock(&rfcomm_dev_lock);

    i = 0;
    list_for_each_entry(struct rfcomm_dev *, dev, &rfcomm_dev_list, list) {
        if (i >= num_devs)
            break;
        if (dev->released)
            continue;
        d[i++] = dev;
    }

    mutex_unlock(&rfcomm_dev_lock);

    if (i != num_devs) {
        kfree(d);
        return -ENOSPC;
    }

    if (copy_to_user(arg, d, num_devs * sizeof(struct rfcomm_dev *))) {
        kfree(d);
        return -EFAULT;
    }

    kfree(d);
    return 0;
}

int retrieve_rfcomm_devices(void __user *arg) {
    int num_devices;
    struct rfcomm_dev **dev_list;
    struct rfcomm_dev_info *info;
    int ret = 0;
    int i = 0;

    if (get_user(num_devices, (int __user *)arg)) {
        return -EFAULT;
    }

    dev_list = kmalloc_array(num_devices, sizeof(struct rfcomm_dev *), GFP_KERNEL);
    if (!dev_list) {
        return -ENOMEM;
    }

    lock_device_list();

    for (i = 0; i < num_devices; i++) {
        dev_list[i] = get_rfcomm_device(i);
        if (!dev_list[i] || dev_list[i]->state == RFCOMM_DEV_RELEASED) {
            ret = -ENODEV;
            break;
        }
    }

    if (ret < 0) {
        unlock_device_list();
        kfree(dev_list);
        return ret;
    }

    info = kmalloc_array(num_devices, sizeof(struct rfcomm_dev_info), GFP_KERNEL);
    if (!info) {
        unlock_device_list();
        kfree(dev_list);
        return -ENOMEM;
    }

    for (i = 0; i < num_devices; i++) {
        info[i].id = dev_list[i]->id;
        info[i].state = dev_list[i]->state;
        info[i].flags = dev_list[i]->flags;
    }

    unlock_device_list();

    if (copy_to_user(arg, info, num_devices * sizeof(struct rfcomm_dev_info))) {
        kfree(dev_list);
        kfree(info);
        return -EFAULT;
    }

    kfree(dev_list);
    kfree(info);
    return 0;
}

#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/rfcomm.h>

int rfcomm_dev_list_get(void __user *arg)
{
    int num_devs, i;
    struct rfcomm_dev **d;
    struct rfcomm_dev_list *list;

    if (get_user(num_devs, (int __user *)arg))
        return -EFAULT;

    if (num_devs <= 0)
        return -EINVAL;

    list = kzalloc(sizeof(*list) + num_devs * sizeof(struct rfcomm_dev *), GFP_KERNEL);
    if (!list)
        return -ENOMEM;

    d = list->devs;
    list->num = 0;

    // Lock device list
    mutex_lock(&rfcomm_dev_lock);

    for (i = 0; i < RFCOMM_MAX_DEVICES; i++) {
        struct rfcomm_dev *dev = rfcomm_devs[i];
        if (!dev || dev->released)
            continue;
        *d++ = dev;
        list->num++;
    }

    // Unlock device list
    mutex_unlock(&rfcomm_dev_lock);

    if (copy_to_user(arg, list, sizeof(*list) + list->num * sizeof(struct rfcomm_dev *))) {
        kfree(list);
        return -EFAULT;
    }

    kfree(list);
    return 0;
}
